import{_ as t,o as e,c as o,ae as r}from"./chunks/framework.BmsPYn1i.js";const k=JSON.parse('{"title":"Controllerについて","description":"","frontmatter":{},"headers":[],"relativePath":"FeaturesIntroduction/Controller/index.md","filePath":"FeaturesIntroduction/Controller/index.md"}'),l={name:"FeaturesIntroduction/Controller/index.md"};function i(s,a,n,h,p,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="controllerについて" tabindex="-1">Controllerについて <a class="header-anchor" href="#controllerについて" aria-label="Permalink to &quot;Controllerについて&quot;">​</a></h1><h2 id="controllerとは" tabindex="-1">Controllerとは <a class="header-anchor" href="#controllerとは" aria-label="Permalink to &quot;Controllerとは&quot;">​</a></h2><p>Controllerは、マウス・タッチ・キーボードなどの<strong>入力を処理する</strong> 役割を持つ部品です。各Viewには1つのControllerが設定されていて、 <code>setController()</code>で切り替えられます。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a3.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AvatarPositionController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(player));</span></span></code></pre></div><p>デフォルトでは、マウスやタッチで視点を回せる <a href="./OrbitController.html">OrbitControllerクラス</a>が設定されています。 入力処理が何もない状態にしたいとき（ゲームでカメラを勝手に 動かされたくないときなど）は、空実装の<code>BaseController</code>を 設定します。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">view.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a3.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BaseController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>独自の操作を作りたいときは、<code>BaseController</code>を継承して必要な メソッド（<code>keyDown()</code>・<code>mouseMove()</code>・毎フレームの<code>update()</code>など） だけをオーバーライドします。</p><p>なお、スマホ向けのジョイスティックUIは、Controllerではなく <a href="./../View/GameCanvas.html">GameCanvasクラス</a>が提供しています。</p><h2 id="orbitcontrollerクラス" tabindex="-1"><a href="./OrbitController.html">OrbitControllerクラス</a> <a class="header-anchor" href="#orbitcontrollerクラス" aria-label="Permalink to &quot;[OrbitControllerクラス](./OrbitController)&quot;">​</a></h2><p>マウスやタッチで視点を回転・ズームできるコントローラー （デフォルト）です。</p><h2 id="avatarpositioncontrollerクラス" tabindex="-1"><a href="./AvatarPositionController.html">AvatarPositionControllerクラス</a> <a class="header-anchor" href="#avatarpositioncontrollerクラス" aria-label="Permalink to &quot;[AvatarPositionControllerクラス](./AvatarPositionController)&quot;">​</a></h2><p>キーボードでキャラクターを動かすコントローラーです。位置指定 方式で、接地判定が安定しています。</p><h2 id="avatarvelocitycontrollerクラス" tabindex="-1"><a href="./AvatarVelocityController.html">AvatarVelocityControllerクラス</a> <a class="header-anchor" href="#avatarvelocitycontrollerクラス" aria-label="Permalink to &quot;[AvatarVelocityControllerクラス](./AvatarVelocityController)&quot;">​</a></h2><p>キーボードでキャラクターを動かすコントローラーです。速度指定 方式で、周囲の剛体と物理的に相互作用できます。</p>',14)])])}const C=t(l,[["render",i]]);export{k as __pageData,C as default};
